        lte(organizations.archivedAt, cutoff),
      ),
    )
    .all();
  return rows.map(toOrganization);
}

/**
 * Permanently removes an organization and every tenant-scoped row it owns.
 * User accounts survive; sessions pointed at the org lose their active org.
 */
export async function purgeOrg(orgId: OrgId): Promise<void> {
  const db = getDb();

  db.transaction((tx) => {
    const tenantTables = [
      webhookDeliveries,
      webhookEndpoints,
      searchIndex,
      rateLimitBuckets,
      notifications,
      notificationPreferences,
      activityEvents,
      attachments,
      comments,
      issueLabels,
      issues,
      labels,
      projectMembers,
      projects,
      invitations,
      members,
      invoices,
      subscriptions,
    ] as const;

    for (const table of tenantTables) {
      tx.delete(table).where(eq(table.orgId, orgId)).run();
    }

    tx.delete(organizationUsage).where(eq(organizationUsage.orgId, orgId)).run();

    tx.update(sessions)
      .set({ activeOrgId: null })
      .where(eq(sessions.activeOrgId, orgId))
      .run();

    tx.delete(organizations).where(eq(organizations.id, orgId)).run();
  });
}

