cd /private/var/folders/82/dclbn8z5181_3ppfdtp8csd40000gn/T/bench-scratch/dd570b78-8378-4b92-896b-ea3766c593b4; mkdir -p tests/tmpsmoke; cat > tests/tmpsmoke/smoke.test.ts <<'EOF'
import { afterAll, beforeAll, expect, it, vi } from "vitest";
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
import { registerActivityListeners } from "@/server/services/activity-service";
import * as orgService from "@/server/services/organization-service";
import { runCleanupArchivedJob } from "@/server/jobs/cleanup-archived-job";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { getDb, activityEvents } from "@/server/db";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); registerActivityListeners(); });
afterAll(() => cleanup());
it("flows", async () => {
  const t = await createTenant("smoke");
  await usageRepo.recomputeUsage(t.org.id);
  await orgService.deleteOrganization(t.actors.owner, { orgId: t.org.id, confirmSlug: t.org.slug });
  await expect(orgService.deleteOrganization(t.actors.owner, { orgId: t.org.id, confirmSlug: t.org.slug })).rejects.toThrow(/already archived/);
  expect(await usageRepo.listOrgIdsForRollup(10)).not.toContain(t.org.id);
  await expect(orgService.restoreOrganization(t.userIds.admin, t.org.id)).rejects.toThrow(/org:restore|denied|permission/i);
  const r = await orgService.restoreOrganization(t.userIds.owner, t.org.id);
  expect(r.archivedAt).toBeNull();
  console.log(getDb().select().from(activityEvents).all().map(a => [a.action, a.subjectId === t.org.id, a.actorId === t.userIds.owner]));
  await orgService.deleteOrganization(t.actors.owner, { orgId: t.org.id, confirmSlug: t.org.slug });
  await runCleanupArchivedJob(new Date(Date.now() + 29 * 86400000));
  expect(await orgRepo.findOrgById(t.org.id)).not.toBeNull();
  const res = await runCleanupArchivedJob(new Date(Date.now() + 30 * 86400000 + 1000));
  console.log(res);
  expect(await orgRepo.findOrgById(t.org.id)).toBeNull();
  await expect(orgService.restoreOrganization(t.userIds.owner, t.org.id)).rejects.toThrow(/not found/);
  const again = await orgService.createOrganization(t.userIds.owner, { name: "x", slug: "smoke", plan: "free" } as never);
  expect(again.slug).toBe("smoke");
});
EOF
npx vitest run tests/tmpsmoke 2>&1 | grep -v "npm warn" | tail -30; rm -rf tests/tmpsmoke

